Thumbs.deleteAll = async (id, preserveFiles = false) => {
	const isDraft = validator.isUUID(String(id));
	const set = `${isDraft ? 'draft' : 'topic'}:${id}:thumbs`;

	if (preserveFiles) {
		await db.delete(set);
		cache.del(set);
		return;
	}
	const thumbs = await db.getSortedSetRange(set, 0, -1);
	await Thumbs.delete(id, thumbs, true);
